    @Test
    @Order(5)
    void shouldRejectConflictingDates() throws Exception {
        String body = """
                {
                    "roomNumber": 201,
                    "guestName": "Pedro Costa",
                    "guestEmail": "pedro@example.com",
                    "guestCpf": "11111111111",
