        JsonNode reservation = mapper.readTree(response.body());
        assertThat(reservation.get("status").asText()).isEqualTo("CANCELLED");
        assertThat(reservation.get("refund").decimalValue()).isEqualByComparingTo("0.00");
    }

    @Test
    @Order(11)
    void shouldGenerateOccupancyReport() throws Exception {
        String body = """
                {
                    "roomNumber": 301,
                    "guestName": "Carlos Souza",
                    "guestEmail": "carlos@example.com",
                    "guestCpf": "33344455566",
                    "checkIn": "2027-05-15",
                    "checkOut": "2027-05-17",
                    "guests": 3,
                    "ratePlan": "STANDARD"
                }
                """;
        post("/reservations", body);
        post("/reservations/4/confirmation", "");

        HttpResponse<String> response = get("/reports/occupancy?date=2027-05-15");
        assertThat(response.statusCode()).isEqualTo(200);

        String csv = response.body();
        String[] lines = csv.split("\n");
        assertThat(lines[0]).isEqualTo("Pousada Maré Alta,occupancy,2027-05-15");
        assertThat(lines[1]).isEqualTo("room,type,reservation,check_in,check_out");
        assertThat(lines[2]).isEqualTo("301,SUITE,4,2027-05-15,2027-05-17");
        assertThat(lines[3]).isEqualTo("total,1/5");
    }

    @Test
    @Order(12)
    void shouldGenerateRevenueReport() throws Exception {
        HttpResponse<String> response = get("/reports/revenue?month=2027-05");
        assertThat(response.statusCode()).isEqualTo(200);

        String csv = response.body();
        String[] lines = csv.split("\n");
        assertThat(lines[0]).isEqualTo("Pousada Maré Alta,revenue,2027-05");
        assertThat(lines[1]).isEqualTo("reservation,room,check_in,check_out,status,amount");
        assertThat(lines[2]).contains("4,301,2027-05-15,2027-05-17,CONFIRMED");
        assertThat(lines[lines.length - 1]).startsWith("total,");
    }

    @Test
    @Order(13)
    void shouldGenerateTourismTaxReport() throws Exception {
        HttpResponse<String> response = get("/reports/tourism-tax?month=2027-05");
        assertThat(response.statusCode()).isEqualTo(200);

        String csv = response.body();
        String[] lines = csv.split("\n");
        assertThat(lines[0]).isEqualTo("Pousada Maré Alta,tourism-tax,2027-05");
        assertThat(lines[1]).isEqualTo("reservation,room,check_in,check_out,guests,nights,tax");
        assertThat(lines[2]).isEqualTo("4,301,2027-05-15,2027-05-17,3,2,27.00");
        assertThat(lines[3]).isEqualTo("total,27.00");
    }

    @Test
    @Order(14)
    void shouldGenerateRatePlansReport() throws Exception {
        HttpResponse<String> response = get("/reports/rate-plans?month=2027-07");
        assertThat(response.statusCode()).isEqualTo(200);

        String csv = response.body();
        String[] lines = csv.split("\n");
        assertThat(lines[0]).isEqualTo("Pousada Maré Alta,rate-plans,2027-07");
        assertThat(lines[1]).isEqualTo("rate_plan,reservations,amount");
        assertThat(lines[2]).startsWith("STANDARD,0,");
        assertThat(lines[3]).contains("NON_REFUNDABLE,1,509.80");
        assertThat(lines[4]).isEqualTo("total,1,509.80");
    }

    private HttpResponse<String> get(String path) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + path))
                .GET()
                .build();
        return client.send(request, HttpResponse.BodyHandlers.ofString());
    }

    private HttpResponse<String> post(String path, String body) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + path))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        return client.send(request, HttpResponse.BodyHandlers.ofString());
    }
}

